import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"CAF design-area weighting scheme (AB#6797)","description":"","frontmatter":{},"headers":[],"relativePath":"design/caf-design-area-weighting.md","filePath":"design/caf-design-area-weighting.md"}'),n={name:"design/caf-design-area-weighting.md"};function r(s,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="caf-design-area-weighting-scheme-ab-6797" tabindex="-1">CAF design-area weighting scheme (AB#6797) <a class="header-anchor" href="#caf-design-area-weighting-scheme-ab-6797" aria-label="Permalink to &quot;CAF design-area weighting scheme (AB#6797)&quot;">​</a></h1><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Every <code>caf.*.yaml</code> rule file previously carried <code>weight: 1.0</code>. <code>Get-Score</code> computes the CAF framework score as a weighted average of each area&#39;s score, weighted by <code>weight</code> (<code>src/assess/engine/Get-Score.ps1</code>, AB#5087). A flat weight of 1.0 across all eight CAF landing zone design areas means Scout&#39;s <code>CAF: Azure Landing Zone</code> roll-up treats the Governance design area (10 verified recommendations) as carrying exactly as much weight in the overall CAF score as the Network topology and connectivity design area (123 verified recommendations, ~155 counting numbered task steps in pages mid-rewrite). Microsoft does not publish a numeric weighting for the landing zone design areas — the <a href="https://learn.microsoft.com/en-us/azure/cloud-adoption-framework/ready/landing-zone/design-areas" target="_blank" rel="noreferrer">design area review process</a> is a sequential checklist, not a scored rubric — but the <em>volume</em> of guidance Microsoft ships per area is itself a signal of how much of the overall &quot;is this landing zone ready&quot; question that area represents. An assessment that scores Governance and Network as equally weighty when Microsoft&#39;s own guidance is 12x larger for one of them produces a CAF score that does not track how much landing-zone risk each area actually carries.</p><h2 id="the-scheme" tabindex="-1">The scheme <a class="header-anchor" href="#the-scheme" aria-label="Permalink to &quot;The scheme&quot;">​</a></h2><p>Weight each design area proportionally to its <strong>verified recommendation count</strong>, normalized so the mean weight across the eight areas is ~1.0 (so a roll-up computed before this change and one computed after differ only in <em>how much each area&#39;s score moves the needle</em>, not in scale).</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weight(area) = recommendation_count(area) / mean(recommendation_count across all 8 areas)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Recommendation counts are the <strong>verified</strong> figures from <a href="https://github.com/Hybrid-Solutions-Cloud/azure-scout/blob/main/pmo/audits/AZURE-SCOUT-AUDIT.md" target="_blank" rel="noreferrer"><code>pmo/audits/AZURE-SCOUT-AUDIT.md</code> §8 Table 2</a>, which were produced by fetching all 43 Microsoft Learn pages across the eight design areas on 2026-07-30 and counting top-level bullets under each page&#39;s <code>## Design recommendations</code> heading (or the area-specific equivalent, e.g. &quot;Management group recommendations&quot;). That table also documents where the prior audit&#39;s figures were wrong (Security was double-counted against network-security pages it only links to; Management and Governance conflated &quot;considerations&quot; bullets with &quot;recommendations&quot; bullets) — this scheme uses the corrected numbers, not the prior ones.</p><table tabindex="0"><thead><tr><th>Design area</th><th>Rule file</th><th style="text-align:right;">Verified recommendations</th><th style="text-align:right;">Mean (365/8 = 45.625)</th><th style="text-align:right;">Weight</th></tr></thead><tbody><tr><td>Azure billing and Microsoft Entra tenant</td><td><code>caf.billing.yaml</code></td><td style="text-align:right;">42</td><td style="text-align:right;">45.625</td><td style="text-align:right;"><strong>0.92</strong></td></tr><tr><td>Identity and access management</td><td><code>caf.identity.yaml</code></td><td style="text-align:right;">65</td><td style="text-align:right;">45.625</td><td style="text-align:right;"><strong>1.42</strong></td></tr><tr><td>Resource organization</td><td><code>caf.resourceorg.yaml</code></td><td style="text-align:right;">35</td><td style="text-align:right;">45.625</td><td style="text-align:right;"><strong>0.77</strong></td></tr><tr><td>Network topology and connectivity</td><td><code>caf.network.yaml</code></td><td style="text-align:right;">123 (formal)</td><td style="text-align:right;">45.625</td><td style="text-align:right;"><strong>2.70</strong></td></tr><tr><td>Security</td><td><code>caf.security.yaml</code></td><td style="text-align:right;">45</td><td style="text-align:right;">45.625</td><td style="text-align:right;"><strong>0.99</strong></td></tr><tr><td>Management</td><td><code>caf.management.yaml</code></td><td style="text-align:right;">15</td><td style="text-align:right;">45.625</td><td style="text-align:right;"><strong>0.33</strong></td></tr><tr><td>Governance</td><td><code>caf.governance.yaml</code></td><td style="text-align:right;">10</td><td style="text-align:right;">45.625</td><td style="text-align:right;"><strong>0.22</strong></td></tr><tr><td>Platform automation and DevOps</td><td><code>caf.platformauto.yaml</code></td><td style="text-align:right;">30</td><td style="text-align:right;">45.625</td><td style="text-align:right;"><strong>0.66</strong></td></tr></tbody></table><p><code>weight</code> lives in each rule file&#39;s YAML header next to a one-line citation back to this document, so a future rule-count change (new rules added, or Microsoft republishing the design-area pages) has a clear place to recompute from.</p><h2 id="what-this-deliberately-does-not-do" tabindex="-1">What this deliberately does NOT do <a class="header-anchor" href="#what-this-deliberately-does-not-do" aria-label="Permalink to &quot;What this deliberately does NOT do&quot;">​</a></h2><ul><li><strong>It does not claim to be Microsoft&#39;s weighting.</strong> Microsoft ships no landing-zone-review scoring weight; this is Scout&#39;s own derived scheme, built from a number Microsoft <em>does</em> publish (recommendation count per area) rather than invented from nothing. The audit and the citation comment in each rule file make this distinction explicit so a reader does not mistake Scout&#39;s weighting for an official Microsoft score.</li><li><strong>It does not change per-area scoring.</strong> Each design-area assessment (see the registry entries added under <code>manifests/assessments.psd1</code> for AB#6797) scores only its own rules at 100% weight internally — the weighting only changes how the eight area scores combine into the single CAF framework number inside the <code>CAF: Azure Landing Zone</code> roll-up and inside <code>Get-Score</code>&#39;s <code>Frameworks</code> output.</li><li><strong>It is not a coverage weight.</strong> Scout&#39;s own rule-count-per-area (6-7 rules per file today) is intentionally NOT used as the weighting basis — that would reward files that happen to be under-built with a lower influence on the score, which is the opposite of what an honest &quot;how much does this area matter&quot; weighting should do. The weighting tracks Microsoft&#39;s guidance volume, not Scout&#39;s current implementation depth.</li></ul><h2 id="reconciliation" tabindex="-1">Reconciliation <a class="header-anchor" href="#reconciliation" aria-label="Permalink to &quot;Reconciliation&quot;">​</a></h2><p>Because <code>Get-Score</code>&#39;s framework score is <em>computed from</em> the area scores it weights (not scored independently), the <code>CAF: Azure Landing Zone</code> roll-up&#39;s CAF framework score is guaranteed, by construction, to equal the weighted average of the eight <code>CAF: &lt;design area&gt;</code> assessments&#39; own framework scores when run against the same collect.json. <code>tests/Assessment.Restructure.Tests.ps1</code> pins this with a non-vacuous test (break the weight, watch the reconciliation assertion fail, restore).</p>',13)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
